package main

import (
    "fmt"
    "strconv"
)

func positive(text string) (int, error) {
    count, err := strconv.Atoi(text)
    if err != nil {
        return 0, fmt.Errorf("reading count: %w", err)
    }
    if count <= 0 {
        return 0, fmt.Errorf("count must be positive")
    }
    return count, nil
}

func main() {
    count, err := positive("8")
    if err != nil {
        fmt.Println(err)
        return
    }
    fmt.Println(count)
}

package main

import (
    "encoding/json"
    "fmt"
    "os"
    "path/filepath"
)

type Score struct {
    Points int `json:"points"`
}

func save() error {
    folder, err := os.MkdirTemp("", "ion-go-")
    if err != nil { return err }
    defer os.RemoveAll(folder)
    file := filepath.Join(folder, "score.json")
    data, err := json.Marshal(Score{Points: 9})
    if err != nil { return err }
    if err := os.WriteFile(file, data, 0600); err != nil { return err }
    saved, err := os.ReadFile(file)
    if err != nil { return err }
    var result Score
    if err := json.Unmarshal(saved, &result); err != nil { return err }
    fmt.Println(result.Points)
    return nil
}

func main() {
    if err := save(); err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
}

package main

import "fmt"

func square(value int, results chan<- int) {
    results <- value * value
}

func main() {
    results := make(chan int)
    go square(7, results)
    fmt.Println(<-results)
}
